#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const ROOT=process.cwd();
const IDS=['L_BURNING_EXPRESS_ZN','L_PRISM_NANA_CC','L_GINGA_EIYUU_DNT_GH','L_HIHODEN_PA7','L_OKIDOKI_DUO_ENCORE_FR','L_HOKUTO_TENSEI_2_MW','L_TEKKEN_6_YD01H','L_HANMA_BAKI_L5','L_GOBLIN_SLAYER_2_JZ','L_GHOST_IN_THE_SHELL_ZS'];
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n','utf8');
const sanitize=s=>String(s??'').normalize('NFKC').toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'')||'VALUE';
const featId=rf=>`FEAT_${sanitize(String(rf).replace(/^RF_/,''))}`;
const inpId=(rf,suffix)=>`INP_${sanitize(String(rf).replace(/^RF_/,''))}_${sanitize(suffix)}`;
const settings=['SET_1','SET_2','SET_3','SET_4','SET_5','SET_6'];
const probDen=d=>1/Number(d);

function paths(id){const d=path.join(ROOT,'research',id);return {d,r:path.join(d,'research-data.json'),s:path.join(d,'selection-data.json'),o:path.join(d,'machine-observation-data.json'),u:path.join(d,'ui-design-data.json')};}
function upsert(arr,key,item){const i=arr.findIndex(x=>x?.[key]===item[key]);if(i>=0)arr[i]=item;else arr.push(item);}
function removeInputs(selection,pred){selection.inputs=(selection.inputs??[]).filter(x=>!pred(x));}
function removeFeatureInputs(selection,feature){const ids=new Set([feature?.numeratorInputId,feature?.denominatorInputId,...(feature?.categoryInputIds??[]),...(feature?.denominatorInputIds??[])].filter(Boolean));removeInputs(selection,x=>ids.has(x.id));}
function setDisposition(selection,rfId,patch){let f=(selection.features??[]).find(x=>x.researchFeatureId===rfId);if(!f){f={researchFeatureId:rfId,featureId:featId(rfId)};(selection.features??=[]).push(f);}Object.assign(f,patch);return f;}
function exclude(selection,rfId,reason){const old=(selection.features??[]).find(x=>x.researchFeatureId===rfId);if(old)removeFeatureInputs(selection,old);const f=setDisposition(selection,rfId,{featureId:featId(rfId),adoptionCategory:'EXCLUDE',weight:1,userFacingReason:reason,rejectionReason:reason,difficultyParticipation:'EXCLUDE'});delete f.numeratorInputId;delete f.denominatorInputId;delete f.categoryInputIds;delete f.denominatorInputIds;delete f.inputTransform;delete f.suppressedByFeatureIds;delete f.userReason;delete f.difficultyExclusionReason;return f;}
function addBinomialSelection(selection,rf,{category='INCLUDE_SUPPORT',reason,suppressedBy=[]}={}){const rfId=rf.researchFeatureId;const num=inpId(rfId,'COUNT'),den=inpId(rfId,'TRIALS'),cat=`SEL_${sanitize(rfId)}`;selection.inputs??=[];removeInputs(selection,x=>x.id===num||x.id===den);const order=Math.max(0,...selection.inputs.map(x=>Number(x.displayOrder)||0))+5;selection.inputs.push({id:num,name:`${rf.name} 回数`,category:cat,type:'counter',unit:'回',displayOrder:order,inferenceRole:category,defaultValue:''},{id:den,name:rf.denominatorDefinition||`${rf.name} 母数`,category:cat,type:'integer',unit:/ゲーム|G$/.test(String(rf.denominatorDefinition))?'G':'回',displayOrder:order+1,inferenceRole:category,defaultValue:''});const f=setDisposition(selection,rfId,{featureId:featId(rfId),adoptionCategory:category,weight:1,numeratorInputId:num,denominatorInputId:den,userReason:reason||'全設定値と観測母数が明示され、独立した観測段階として評価できるため採用する。',difficultyParticipation:'EXCLUDE',difficultyExclusionReason:'今回の実機フィードバック再SelectionではDifficulty再較正前のため推測Featureのみ更新する。'});delete f.userFacingReason;delete f.rejectionReason;delete f.categoryInputIds;delete f.denominatorInputIds;delete f.inputTransform;if(suppressedBy.length)f.suppressedByFeatureIds=suppressedBy.map(featId);else delete f.suppressedByFeatureIds;selection.uiCategoryLabels??={};selection.uiCategoryLabels[cat]=rf.name;return f;}
function addMultinomialSelection(selection,rf,{category='INCLUDE_SUPPORT',reason}={}){const rfId=rf.researchFeatureId,cat=`SEL_${sanitize(rfId)}`;selection.inputs??=[];const existing=(selection.features??[]).find(x=>x.researchFeatureId===rfId);if(existing)removeFeatureInputs(selection,existing);const order=Math.max(0,...selection.inputs.map(x=>Number(x.displayOrder)||0))+5;const ids=rf.categories.map((name,i)=>{const id=inpId(rfId,`CAT_${i+1}`);selection.inputs.push({id,name,category:cat,type:'counter',unit:'回',displayOrder:order+i,inferenceRole:category,defaultValue:''});return id;});const f=setDisposition(selection,rfId,{featureId:featId(rfId),adoptionCategory:category,weight:1,numeratorInputId:ids[0],categoryInputIds:ids.slice(1),denominatorInputIds:ids,inputTransform:'sum_inputs_to_trials',userReason:reason||'設定別の完全な振り分けを、同一機会内の排他的カテゴリとしてまとめて評価できるため採用する。',difficultyParticipation:'EXCLUDE',difficultyExclusionReason:'今回の実機フィードバック再SelectionではDifficulty再較正前のため推測Featureのみ更新する。'});delete f.userFacingReason;delete f.rejectionReason;delete f.denominatorInputId;delete f.suppressedByFeatureIds;selection.uiCategoryLabels??={};selection.uiCategoryLabels[cat]=rf.name;return f;}
function sv(raw){return Object.fromEntries(Object.entries(raw).map(([s,d])=>[s,{probability:typeof d==='number'?d:d.p,rawDisplay:typeof d==='number'?`${(d*100).toFixed(3)}%`:d.rawDisplay??`${(d.p*100).toFixed(3)}%`}]))}
function dist(raw){return Object.fromEntries(Object.entries(raw).map(([s,v])=>[s,v]));}

// 1) Burning Express: decompose reel-lock aggregate and reject the low-signal reach-me component.
{
 const p=paths('L_BURNING_EXPRESS_ZN'),r=read(p.r),s=read(p.s);r.features??=[];
 const nonReach={researchFeatureId:'RF_REEL_LOCK_NON_REACH',name:'リーチ目以外のリールロック',factStatus:'verified',candidateModel:'binomial',trialUnit:'通常ゲーム',numeratorDefinition:'チェリー・スイカ・その他のリールロック回数（リーチ目を除く）',denominatorDefinition:'通常ゲーム数',settingValues:{SET_1:{probability:0.0006507070402045473,rawDisplay:'約1/1536.8'},SET_2:{probability:0.0006541543141825932,rawDisplay:'約1/1528.7'},SET_4:{probability:0.0007162916546639776,rawDisplay:'約1/1396.1'},SET_5:{probability:0.0007549662283271292,rawDisplay:'約1/1324.6'},SET_6:{probability:0.0007721640734433264,rawDisplay:'約1/1295.1'}},sourceRefs:['SRC_NANA_SETTING'],crossSourceStatus:'derived_from_verified_component_rates',notes:'公開されたチェリー・スイカ・その他の通常時リールロック率を設定別に合算。設定差がほぼないリーチ目ロックを除外して判別信号を希釈しない。'};
 const reach={researchFeatureId:'RF_REEL_LOCK_REACH',name:'リールロック時リーチ目',factStatus:'verified',candidateModel:'binomial',trialUnit:'通常ゲーム',numeratorDefinition:'リーチ目を伴うリールロック回数',denominatorDefinition:'通常ゲーム数',settingValues:{SET_1:{probability:probDen(1338.7),rawDisplay:'1/1338.7'},SET_2:{probability:probDen(1338.5),rawDisplay:'1/1338.5'},SET_4:{probability:probDen(1337.5),rawDisplay:'1/1337.5'},SET_5:{probability:probDen(1337.9),rawDisplay:'1/1337.9'},SET_6:{probability:probDen(1339.2),rawDisplay:'1/1339.2'}},sourceRefs:['SRC_NANA_SETTING'],crossSourceStatus:'single_source',notes:'設定1〜6で約1/1338とほぼ不変。'};
 upsert(r.features,'researchFeatureId',nonReach);upsert(r.features,'researchFeatureId',reach);
 exclude(s,'RF_REEL_LOCK_TOTAL','リールロック合算は、最も頻度の高いリーチ目ロックが設定1〜6で約1/1338とほぼ不変で、チェリー・スイカ・その他にある設定差を薄めるため不採用。リーチ目以外を分離して評価する。');
 exclude(s,'RF_REEL_LOCK_REACH','リーチ目を伴うリールロックは設定1〜6で約1/1337.5〜1/1339.2と差がほぼなく、設定推測への寄与が極めて小さいため不採用。');
 addBinomialSelection(s,nonReach,{category:'INCLUDE_FALLBACK',suppressedBy:['RF_EXPRESS_BONUS_INITIAL'],reason:'設定差がほぼないリーチ目を除いたリールロックだけを評価する。ボーナス経路との事象重複を避けるため、エクスプレスボーナス初当りが利用できない場合のFallbackとして採用する。'});
 r.researchNotes??=[];r.researchNotes.push('2026-09-06実機フィードバック再Selection: リールロック合算はリーチ目が設定差を希釈するため分解。非リーチ目ロックをFallback、リーチ目ロックをEXCLUDE。');write(p.r,r);write(p.s,s);
}

