  FIRE:{SET_1:[.625,.375],SET_2:[.375,.625],SET_3:[.625,.375],SET_4:[.387076796,.612923204],SET_5:[.612923204,.387076796],SET_6:[.4,.6]},
  SWEET:{SET_1:[.625,.375],SET_2:[.375,.625],SET_3:[.625,.375],SET_4:[.4285714286,.5714285714],SET_5:[.5714285714,.4285714286],SET_6:[.5,.5]}
