 const talk=mk('RF_NORMAL_TALK_NON_EVIDENCE','通常時の特定会話（確定系を除く）',['そうね、きれいな青空ね','ぐっすり昼寝をしたいわね','踊りたくなってしまうような天気ね！','ロケット愛は流石ね'],{SET_1:{'そうね、きれいな青空ね':.4375,'ぐっすり昼寝をしたいわね':.3125,'踊りたくなってしまうような天気ね！':.1875,'ロケット愛は流石ね':.0625},SET_2:{'そうね、きれいな青空ね':.3125,'ぐっすり昼寝をしたいわね':.4375,'踊りたくなってしまうような天気ね！':.1875,'ロケット愛は流石ね':.0625},SET_3:{'そうね、きれいな青空ね':.3749625037,'ぐっすり昼寝をしたいわね':.2812718728,'踊りたくなってしまうような天気ね！':.2187781222,'ロケット愛は流石ね':.1249875012},SET_4:{'そうね、きれいな青空ね':.2823730175,'ぐっすり昼寝をしたいわね':.3725155591,'踊りたくなってしまうような天気ね！':.2196346115,'ロケット愛は流石ね':.1254768119},SET_5:{'そうね、きれいな青空ね':.3070953437,'ぐっすり昼寝をしたいわね':.2519653296,'踊りたくなってしまうような天気ね！':.2519653296,'ロケット愛は流石ね':.1889739972},SET_6:{'そうね、きれいな青空ね':.2529596276,'ぐっすり昼寝をしたいわね':.304361024,'踊りたくなってしまうような天気ね！':.2529596276,'ロケット愛は流石ね':.1897197207}},'非Evidence会話パターン回数','非Evidenceの対象会話確認回数');
 for(const rf of [end,music,...voices,talk]){upsert(r.features,'researchFeatureId',rf);addMultinomialSelection(s,rf,{reason:'設定別の振り分けが公開されており、Hard Evidenceパターンを除外して再正規化した排他的カテゴリとして評価できるため補助Featureに採用する。確定系が出た場合は数値側に数えずEvidenceだけへ入力する。'});}
