// 3) Hihoden: preserve mystery-high data but reject numeric inference until an exact non-Densetsu denominator is observable.
{
 const p=paths('L_HIHODEN_PA7'),r=read(p.r),s=read(p.s);const rf={researchFeatureId:'RF_REPLAY_MYSTERY_HIGH',name:'リプレイ契機の高確率（謎高確率）',factStatus:'verified',candidateModel:'binomial',trialUnit:'否伝説モード中の通常ゲーム',numeratorDefinition:'否伝説モード中のリプレイ契機高確率当選回数',denominatorDefinition:'否伝説モード中の通常ゲーム数',settingValues:{SET_1:{probability:probDen(5471.1),rawDisplay:'1/5471.1'},SET_2:{probability:probDen(4602.1),rawDisplay:'1/4602.1'},SET_3:{probability:probDen(3724.1),rawDisplay:'1/3724.1'},SET_4:{probability:probDen(2559.6),rawDisplay:'1/2559.6'},SET_5:{probability:probDen(2241.0),rawDisplay:'1/2241.0'},SET_6:{probability:probDen(2060.6),rawDisplay:'1/2060.6'}},sourceRefs:['SRC_1GEKI_SETTING','SRC_NANA_SETTING'],crossSourceStatus:'cross_checked',notes:'設定差は大きい。リプレイ契機の当選回数はダイトモ等で確認可能だが、公表率は否伝説モードを条件とする。伝説モード滞在Gを完全除外したeligible denominatorを実戦中に再現できないためSelectionで母数監査が必要。'};r.features??=[];upsert(r.features,'researchFeatureId',rf);exclude(s,rf.researchFeatureId,'設定差は大きく、リプレイ契機の当選回数も確認できるが、公表値は「否伝説モード中」を条件とした出現率。伝説モード滞在ゲームを完全に除外した母数を実戦中に正確取得できず、総通常ゲーム数で代用すると伝説モード滞在差まで混入して母数契約違反になるため現時点では不採用。');r.researchNotes??=[];r.researchNotes.push('2026-09-06実機フィードバック再Selection: 謎高確率は数値差を確認したが、否伝説モード中Gというeligible denominatorを正確観測できないためEXCLUDE。ダイトモで分子を確認できても母数問題は解消しない。');write(p.r,r);write(p.s,s);
}

