 const atDirect={researchFeatureId:'RF_AT_DIRECT',name:'通常時AT直撃',factStatus:'verified',candidateModel:'binomial',trialUnit:'通常ゲーム',numeratorDefinition:'通常時のAT直撃回数',denominatorDefinition:'通常ゲーム数',settingValues:{SET_1:{probability:probDen(12580.4),rawDisplay:'1/12580.4'},SET_2:{probability:probDen(10774.5),rawDisplay:'1/10774.5'},SET_3:{probability:probDen(7471.1),rawDisplay:'1/7471.1'},SET_4:{probability:probDen(5347.4),rawDisplay:'1/5347.4'},SET_5:{probability:probDen(3840.1),rawDisplay:'1/3840.1'},SET_6:{probability:probDen(3565.2),rawDisplay:'1/3565.2'}},sourceRefs:['SRC_1GEKI_SETTING','SRC_NANA_SETTING'],crossSourceStatus:'cross_checked',notes:'AT初当りに内包される部分事象。'};
 const weak={researchFeatureId:'RF_BONUS_DIRECT_WEAK_GROUP',name:'弱チェリー・スイカ・チャンス目からのボーナス直撃',factStatus:'verified',candidateModel:'binomial',trialUnit:'対象弱レア役成立',numeratorDefinition:'弱チェリー・スイカ・チャンス目からのボーナス直撃回数',denominatorDefinition:'弱チェリー・スイカ・チャンス目成立回数',settingValues:sv({SET_1:.004,SET_2:.004,SET_3:.004,SET_4:.016,SET_5:.016,SET_6:.016}),sourceRefs:['SRC_1GEKI_SETTING','SRC_NANA_SETTING'],crossSourceStatus:'cross_checked',notes:'ボーナス初当りに内包される部分事象。'};
